import { MakeLogicType, actions, connect, kea, key, listeners, path, props, reducers, selectors } from 'kea'
import posthog from 'posthog-js'

import { playerSidebarLogic } from 'scenes/session-recordings/player/sidebar/playerSidebarLogic'

import { SessionRecordingSidebarTab } from '~/types'

export type ReplayListSegment = 'picks' | 'recordings' | 'moments'
export type ReplayListSegmentSource = 'user' | 'observations'
export type ReplayListPicksMode = 'picks' | 'recordings' | null

export interface ReplayListColumnLogicProps {
    logicKey: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface replayListColumnLogicValues {
    effectiveSegmentFor: (picksMode: ReplayListPicksMode, momentsAvailable: boolean | null) => ReplayListSegment
    segment: ReplayListSegment | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface replayListColumnLogicActions {
    setSidebarTab: (tab: SessionRecordingSidebarTab) => {
        tab: SessionRecordingSidebarTab
    } // playerSidebarLogic
    dropSegmentChoice: () => {
        value: true
    }
    setSegment: (
        segment: ReplayListSegment,
        source?: ReplayListSegmentSource
    ) => {
        segment: ReplayListSegment
        source: ReplayListSegmentSource
    }
    settleSegment: (
        picksMode: ReplayListPicksMode,
        momentsAvailable: boolean | null
    ) => {
        momentsAvailable: boolean | null
        picksMode: ReplayListPicksMode
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface replayListColumnLogicMeta {
    key: string
    __keaTypeGenInternalSelectorTypes: {
        effectiveSegmentFor: (
            segment: ReplayListSegment | null
        ) => (picksMode: ReplayListPicksMode, momentsAvailable: boolean | null) => ReplayListSegment
    }
}

export type replayListColumnLogicType = MakeLogicType<
    replayListColumnLogicValues,
    replayListColumnLogicActions,
    ReplayListColumnLogicProps,
    replayListColumnLogicMeta
>

export const replayListColumnLogic = kea<replayListColumnLogicType>([
    path((key) => ['scenes', 'session-recordings', 'playlist', 'replayListColumnLogic', key]),
    props({} as ReplayListColumnLogicProps),
    key((props) => props.logicKey),
    connect(() => ({
        actions: [playerSidebarLogic, ['setTab as setSidebarTab']],
    })),
    actions({
        setSegment: (segment: ReplayListSegment, source: ReplayListSegmentSource = 'user') => ({ segment, source }),
        // Or the choice resurfaces on a later recording.
        dropSegmentChoice: true,
        settleSegment: (picksMode: ReplayListPicksMode, momentsAvailable: boolean | null) => ({
            picksMode,
            momentsAvailable,
        }),
    }),
    reducers({
        // Null until the viewer picks one, so the picks logic keeps deciding where a fresh page lands.
        segment: [
            null as ReplayListSegment | null,
            { setSegment: (_, { segment }) => segment, dropSegmentChoice: () => null },
        ],
    }),
    selectors({
        effectiveSegmentFor: [
            (s) => [s.segment],
            (segment: ReplayListSegment | null) =>
                (picksMode: ReplayListPicksMode, momentsAvailable: boolean | null): ReplayListSegment => {
                    const chosen = segment ?? picksMode ?? 'recordings'
                    if (chosen === 'picks' && picksMode === null) {
                        return 'recordings'
                    }
                    if (chosen === 'moments' && !momentsAvailable) {
                        return 'recordings'
                    }
                    return chosen
                },
        ],
    }),
    listeners(({ actions, values }) => ({
        setSegment: ({ segment, source }) => {
            posthog.capture('session recording list segment changed', { segment, source })
        },
        settleSegment: ({ picksMode, momentsAvailable }) => {
            const chosen = values.segment
            if ((chosen === 'picks' && picksMode === null) || (chosen === 'moments' && momentsAvailable === false)) {
                actions.dropSegmentChoice()
            }
        },
        // Summarize and View details still ask for the Observations tab. In this layout that content is the Moments segment.
        setSidebarTab: ({ tab }) => {
            if (tab === SessionRecordingSidebarTab.OBSERVATIONS && values.segment !== 'moments') {
                actions.setSegment('moments', 'observations')
            }
        },
    })),
])
